class Solution {
public:
    int passThePillow(int n, int time) {
        int cycle = 2 * (n - 1);
        int rem = time % cycle;
        if (rem < n) return 1 + rem;
        return n - (rem - (n - 1));
    }
};

class Solution {
    public int passThePillow(int n, int time) {
        int cycle = 2 * (n - 1);
        int rem = time % cycle;
        if (rem < n) return 1 + rem;
        return n - (rem - (n - 1));
    }
}

var passThePillow = function(n, time) {
